python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); X = train.drop(columns=['target']).values; 
def get_poly_features(X):
    n_samples, n_features = X.shape
    out = [np.ones(n_samples), X.T]
    for i in range(n_features):
        out.append((X[:, i:] * X[:, i:i+1]).T)
    return np.column_stack(out)
X_poly = get_poly_features(X); print(X_poly.shape)"
